,"type":"text","required":true,"showWhen":{"id":"institution","equals":["ALX","Other"]}},{"id":"disability","label":"Do you identify as a person living with a disability?","type":"single","required":true,"options":["Yes","No"],"showWhen":{"id":"institution","equals":["ALX","Other"]}},{"id":"humanitarian","label":"Which of the following humanitarian statuses do you identify with?","type":"single","required":true,"options":["Refugee","Asylum seeker","Internally Displaced Person (IDP)","None"],"showWhen":{"id":"institution","equals":["ALX","Other"]}},{"id":"current_status","label":"Which best describes your current status?","type":"single","required":true,"options":["Wage Employment","Self-employed / Entrepreneur","Freelance","Unemployed","Student","Pursuing further education"],"showWhen":{"id":"institution","equals":["ALX","Other"]}},{"id":"consent","label":"I consent to my information being used to run this programme and for monitoring, evaluation and learning.","type":"consent","required":true},{"id":"sessions","label":"Which masterclasses would you like to register for?","type":"multi","required":true,"options":["Budgeting, Cash Flow & Startup Finance (Fri 30 Oct)","Financial Projections & Decision Making (Fri 6 Nov)","Funding Strategy & Investor/Grant Readiness (Fri 13 Nov)","Financial Storytelling, Pitching & Finance Clinic (Fri 20 Nov)"]},{"id":"knowledge","label":"How would you describe your current knowledge of startup finance?","type":"single","required":true,"options":["None: I have no experience with budgeting or financial planning","Beginner: I understand the basics","Intermediate: I have made a budget, cash flow plan or financial projection","Advanced: I regularly manage budgets, projections or fundraising for a venture"]},{"id":"hope","label":"What is one thing you hope to gain from this masterclass series?","type":"long","required":true}]$json$::jsonb
